      "ids": ["EFF-01", "EFF-03"],
      "type": "resource",
      "description": "The push for performance may lead to higher energy consumption, conflicting with GRN-01 and GRN-05."
    },
    {
      "ids": ["EFF-07"],
      "type": "logical",
      "description": "Prioritizing smoothness over energy efficiency during emergencies may lead to increased energy use."
    }
  ],
